#!/usr/bin/env bash
# Example two: Key Vault first. The key pair and CSR are generated by Key Vault; Let's Encrypt signs the CSR
# (certbot certonly --csr, DNS-01 in Azure DNS); the signed chain is merged back into the pending request.
# ONE idempotent script: it reads the certificate's expiry in Key Vault and exits when renewal isn't due, so it is safe
# to call from anything, as often as you like (see README.md: Event Grid near-expiry event -> Automation runbook,
# a cron/systemd timer, or a pipeline schedule). Sign-in: managed identity, or OIDC / workload identity federation.
# Needs:
#   - Key Vault Certificates Officer on the vault (RBAC permission model)
#   - DNS rights ONLY on a small challenge-only zone: _acme-challenge.<domain> is a CNAME into that zone
#     (Let's Encrypt: CNAME records can delegate answering the challenge to other DNS zones)
# AUTH_MODE=plugin (default): community plugin certbot-dns-azure (third-party, not in certbot's official list)
# AUTH_MODE=hooks: no plugin, --manual with auth-hook.sh / cleanup-hook.sh (az network dns record-set txt)
# certbot renew does not manage --csr certificates: this schedule IS the renewal.
# NOT RUN against Azure or Let's Encrypt. See VALIDATION.md.
set -euo pipefail

KV="${KV:-kv-pinecone}"                       # key vault name (fictional)
CERT="${CERT:-wildcard}"                      # certificate name in Key Vault
EMAIL="${ACME_EMAIL:?set ACME_EMAIL}"         # ACME account contact
# Renew when fewer days than this are left. 30 matches Key Vault's near-expiry event (30 days before expiry).
# Arithmetic, not a doc claim: for a 45- or 47-day certificate, 30 days before expiry is around day 15-17 of its life,
# still well before the end, so the same threshold works after the lifetimes shrink.
RENEW_DAYS="${RENEW_DAYS:-30}"
# certbot's config dir holds the ACME account. In a fresh container either persist it (one account) or rely on the
# expiry check below, so a new account is only registered when a renewal is actually due. Never issue daily.
CONFIG_DIR="${CERTBOT_CONFIG_DIR:-$HOME/certbot-config}"
AUTH_MODE="${AUTH_MODE:-plugin}"
AZURE_INI="${AZURE_INI:-$(cd "$(dirname "$0")" && pwd)/azure.ini}"
# Staging until the whole chain works; then set ACME_SERVER to the production directory.
SERVER="${ACME_SERVER:-https://acme-staging-v02.api.letsencrypt.org/directory}"
HERE="$(cd "$(dirname "$0")" && pwd)"
WORK="$(mktemp -d)"
export DNS_RG DNS_ZONE DNS_RECORD

# Signed in already (pipeline OIDC login)? Otherwise use the managed identity.
az account show >/dev/null 2>&1 || az login --identity   # user-assigned: az login --identity --client-id <client_id>

# Skip if the current version still has enough time left (attribute path: see VALIDATION.md)
if expires="$(az keyvault certificate show --vault-name "$KV" -n "$CERT" --query attributes.expires -o tsv 2>/dev/null)" && [ -n "$expires" ]; then
  left=$(( ( $(date -d "$expires" +%s) - $(date +%s) ) / 86400 ))
  if [ "$left" -ge "$RENEW_DAYS" ]; then echo "$CERT: $left days left, nothing to do"; exit 0; fi
fi

# 1. New version: Key Vault generates the key pair and a CSR (issuer "Unknown" in policy.json)
az keyvault certificate create --vault-name "$KV" -n "$CERT" -p @"$HERE/policy.json"
# If anything below fails, drop the pending request so the next run starts clean
trap 'az keyvault certificate pending delete --vault-name "$KV" -n "$CERT" >/dev/null 2>&1 || true' ERR

# 2. Read the CSR from the pending operation (base64 DER) and write it as a DER file
az keyvault certificate pending show --vault-name "$KV" -n "$CERT" --query csr -o tsv | base64 -d > "$WORK/req.der"

# 3. Let's Encrypt signs it with DNS-01. Reuses the account in CONFIG_DIR if it exists.
if [ "$AUTH_MODE" = plugin ]; then
  AUTH=(--authenticator dns-azure --preferred-challenges dns --dns-azure-config "$AZURE_INI")
else
  AUTH=(--manual --preferred-challenges dns
        --manual-auth-hook "$HERE/auth-hook.sh" --manual-cleanup-hook "$HERE/cleanup-hook.sh")
fi
certbot certonly --csr "$WORK/req.der" "${AUTH[@]}" \
  --cert-path "$WORK/cert.pem" --chain-path "$WORK/chain.pem" --fullchain-path "$WORK/fullchain.pem" \
  --config-dir "$CONFIG_DIR" --work-dir "$WORK/work" --logs-dir "$WORK/logs" \
  --server "$SERVER" -n --agree-tos -m "$EMAIL"

# 4. Merge the signed chain into the SAME pending request (otherwise the key won't match)
az keyvault certificate pending merge --vault-name "$KV" -n "$CERT" -f "$WORK/fullchain.pem"
trap - ERR
rm -rf "$WORK"   # no certificate files left behind (the private key never left Key Vault anyway)
echo "$CERT: new version merged"
